from ute_ue.lteue import LteUe
from ute_ue.voice_call import VoiceCall
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer


class VoiceCall(VoiceCall):
    def __int__(self, vc):
        self.__vc = vc

    def await_voice_call_finish(self):
        """
        Waits until ongoing voice call is finished.
        """
        return self.__vc.await_voice_call_finish()

    def hold(self):
        """
        Hold active voice call
        :return:
        """
        return self.__vc.hold()

    def retrieve(self):
        """
        Retrieve held voice call
        :return:
        """
        return self.__vc.retrieve()

    def answer(self, with_video: bool = False):
        """
        Perform answer incoming voice call on UE PC.
        :type with_video:
        :return:
        """
        return self.__vc.answer(with_video)

    def drop(self):
        """
        Drop incoming voice call
        :return:
        """
        return self.__vc.drop()

    def get_state(self):
        """
        Returns voice_call actual state.
        :return str: voice_call state
        """
        return self.__vc.get_state()

    def upgrade(self):
        """
       Upgrades to video call
       :return:
        """
        return self.__vc.upgrade()

    def downgrade(self):
        """
       Downgrades from video call
       :return:
        """
        return self.__vc.downgrade()

    def send_dtmf(self, *args):
        """
        Sends DTMF tones through voice channel.
        :param tones:
        :param tone_duration:
        :return:
        """
        return self.__vc.send_dtmf(*args)

    def __getattr__(self, item):
        attr = getattr(self.__vc, item)
        return attr


class DataTransfer(LteDataTransfer):
    def __int__(self, dt):
        self.__dt = dt

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        return self.__dt.start()

    def stop(self, should_raise: bool = True):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :param should_raise: Allow to raise an exception or rather to log warning
        :return: None
        """
        return self.__dt.stop(should_raise)

    def await_finish(self):
        """
        Waits until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        return self.__dt.await_finish()

    def is_running(self):
        """
        Checks if both client and server are running:
        App Server: checks if paramiko connection has command exit status
        UE: checks if data transfer on UEPC is in active state
        Check is skipped if data transfer earlier was stopped, False is returned immediately
        :return: boolean
        """
        return self.__dt.is_running()

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""
        return self.__dt.check_data_transfer()

    def get_average_throughput(self, **kwargs):  # noqa: C901
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or
        from 'dt.start()' to 'dt.stop()' if data transfer is already finished or
        with currently available iperf intervals that were already transferred.

        :param omit: it is a delay in seconds to start counting the throughput
                     ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the throughput
                    ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: Kbits/sec
        """
        return self.__dt.get_average_throughput(**kwargs)

    def release_data_transfer(self):
        """Releases resources on remote UE PC."""
        return self.__dt.release_data_transfer()

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        return self.__dt.get_datagram_loss()

    def get_client_report_rows(self):
        """
        Returns client iperf report received after stop data transfer, or empty list.
        :return: List[IperfServerReportRow]
        """
        return self.__dt.get_client_report_rows()

    def __getattr__(self, item):
        attr = getattr(self.__dt, item)
        return attr


class Ue(LteUe):
    def __init__(self, ue):
        self.__ue = ue

    def create_data_transfer(self, name: str, **kwargs) -> DataTransfer:
        """
        Create Data Transfer instance for Android UE.

        :param name: str: Data Transfer Alias name
        :return: Instance of data transfer
        """
        return self.__ue.create_data_transfer(name, **kwargs)

    def create_voice_call(self, name: str, **kwargs) -> VoiceCall:
        """
        Create Voice Call instance for Android UE.

        Optional argument is `to` for other UE alias or str representation of call number.

        :param name: str: Voice Call Alias
        :return: Instance of voice call
        """
        return self.__ue.create_voice_call(name, **kwargs)

    def turn_mobile_data_on(self):
        """Turns mobile data on."""
        return self.__ue.turn_mobile_data_on()

    def turn_mobile_data_off(self):
        """Turns mobile data off."""
        return self.__ue.turn_mobile_data_off()

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        return self.__ue.prepare_ue()

    def send_ussd_message(self, ussd_request: str):
        """
        Sends new USSD request form UE to network
        Only runnable on devices with Android 8.0 or higher.
        :param ussd_request:USSD request code which we want to sent to network
        :raises: :py:class:`UeProcedureError`: If UE this method is runs on Android lower than 8.0
        :return:
        """
        return self.__ue.send_ussd_message(ussd_request)

    def get_ussd_response(self, *args):
        """
        Gets USSD code response from network and validates with expected result
        Only runnable on devices with Android 8.0 or higher.
        :param ussd_request_response:USSD code for which we want to retrieve response for validation
        :param expected_result:Response string we expect to get
        :raises: :py:class:`UeProcedureError`: If UE this method is runs on Android lower than 8.0
        :raises: :py:class:`UeProcedureError`: If expected result is different than actual result
        :return: True if result was same as expected result
        """
        return self.__ue.get_ussd_response(*args)

    def start_audio_playback(self, *args, **kwargs):
        """
        Executes commands required to inject voice into voice call and starts playback of specified audio file on UE
        :param audio_file_path: absolute path to audio file on UE
        :param alsa_mixer_command: Cmd to run alsa amixer. Because some UEs might have different commands,
        user can specify command run to fit her/his needs
        :return:
        """
        return self.__ue.start_audio_playback(*args, **kwargs)

    def stop_audio_playback(self):
        """
        Stops previously started audio playback on UE
        This won't stop audio playback from apps other than UeManager!
        :return:
        """
        return self.__ue.stop_audio_playback()

    def get_active_network_technology(self):
        """
        Gets current network technology name: ['-', '?', '2G', '3G', '4G', 'WIFI']
        Where '-' means disconnected.
        Where '?' means unknown.
        :return: Current network technology name.
        """
        return self.__ue.get_active_network_technology()

    def start_reservation_veryfying(self):
        """After this call, this android UE verifies if it's have uptodate reservation on UE PC."""
        return self.__ue.start_reservation_veryfying()

    def start_rrc_logs(self, diag_cfg_path=None, qmdl_size=None):
        """
        Start diag_mdlog on Android UE - start collecting qmdl file with rrc messages from qualcomm chipset.
        :param diag_cfg_path: path to DIAG.cfg file on Windows UE PC
                              (required to run diag_mdlog application on Android UE)
        :param qmdl_size: maximum qmdl file size in MB, int to specify the qmdl size if needed
        :return: Start RRC Logs endpoint status
        :raise DiagCfgFileNotFoundError: "diag_cfg_path" parameter not set!
        :raise QcatExeNotFoundError: "qcat_path parameter" not set!
        """
        return self.__ue.start_rrc_logs(diag_cfg_path, qmdl_size)

    def stop_rrc_logs(self, **kwargs):
        """
        Stop diag_mdlog application on Android UE, convert qmdl to .txt and return path to txt file on UE PC
        :param qcat_analyzer: '-analyzer' value used in QCAT command.
        :param transfer_log_files_from_uepc: if True, transfer log files from UE PC to UE PC
        :param timeout: timeout for transferring log files from UE PC to Robot VM
        :param logs_download_directory: path to directory on UE PC where log files will be downloaded
        :param log_zip_name: name of zip file with logs
        :param filter_file_path: path to filter file on UE PC
        :param mdm: mdm name
        :param return_rrc_log: (deprecated) if True warning will be printed
        :param use_decoding: if True, use decoding
        :return: Stop RRC Logs endpoint status
        """
        return self.__ue.stop_rrc_logs(**kwargs)

    def android_keep_reservation(self):
        """Perform keep reservation on UE PC."""
        return self.__ue.android_keep_reservation()

    def reboot_ue(self, timeout: int = 120):
        """
        Reboot Android ue and wait until it boots
        :param timeout - waiting time in seconds for android ue after reboot
        """
        return self.__ue.reboot_ue(timeout)

    def clear_naa_storage(self):
        """
        Deletes unneeded files from NAA app directory to free up some space.
        """
        return self.__ue.clear_naa_storage()

    def get_ue_info(self, infos_list: str):
        """
        Returns specified UE information, which can be assigned to Robot variable.
        :param infos_list: info(s) to be returned, 'ALL' by default.
        """
        return self.__ue.get_ue_info(infos_list)

    def change_apn(self, apn_name: str, labels_to_apn_settings: str = None, apn_switcher_widget: str = 'android.widget.RadioButton'):
        """
        Tries to switch APN
        :param apn_name: Name of APN, which already exists in APN settings
        :param labels_to_apn_settings: Labels separated by comma eg. Connections,Mobile networks,Access Point Names
        :param apn_switcher_widget: Switcher widget in apn settings, by default. android.widget.RadioButton
        :return:
        """
        return self.__ue.change_apn(apn_name, labels_to_apn_settings, apn_switcher_widget)

    def kill_vysor_process(self):
        """
        Kill Vysor Process
        :return:
        """
        return self.__ue.kill_vysor_process()

    def check_voicemail_notification(self, expected_result: int = -1):
        """
        Checks how many voicemail notifications there is on UE.
        If expected result is not provided, we assume that any amount of voicemail is an acceptable result.
        Only runnable on devices with Android 4.4 or higher.
        :param expected_result: Expected number of notifications
        :raises: :py:class:`UeProcedureError`: if expected result differs from actual
        :return:
        """
        return self.__ue.check_voicemail_notification(expected_result)

    def clear_voicemail_notification(self):
        """
        Clears notification about voicemail.
        Check voicemail notification will return 0 unless new voicemail appears.
        Also cleans on-screen voicemail notifications.
        :return:
        """
        return self.__ue.clear_voicemail_notification()

    def voice_call_to_ue(self, *args, **kwargs):
        """
        Calls voice call to other UE.
        :param name: Voice call alias
        :param other_ue: AndroidUe
        :return: outcomming_voice_call:AndroidOutgoingVoiceCall, incomming_voice_call:AndroidIncomingVoiceCall
        """
        return self.__ue.voice_call_to_ue(self, *args, **kwargs)

    def is_able_voice_call_answer_and_conference(self):
        """
        Returns true if on this UE it is not able to answer voice call via start_voice_call or conference.
        :return: bool
        """
        return self.__ue.is_able_voice_call_answer_and_conference()

    def ensure_able_voice_call_answer_and_conference(self):
        """Raises exception if on this UE it is not able to answer voice call via start_voice_call or conference."""
        return self.__ue.ensure_able_voice_call_answer_and_conference()

    def get_voice_call_dialing_timeout(self):
        """
        Voice_call_dialing_timeout is a time between: start calling from UE TO answer call from receiver
        If voice call has not voice_call_dialing_timeout defined,
        then Voice Call would have UE's voice_call_dialing_timeout
        :return: voice_call_dialing_timeout
        """
        return self.__ue.get_voice_call_dialing_timeout()

    def set_service_mode(self, mmi_code: str, actions_path: str):
        """
        Set service mode on UE using MMI code via phone call menu
        :param mmi_code: Code entered like a phone number to check/set UE ineternal data.
        This code don't need validation by enetring phone call button. Example: '*#73#'
        :param actions_path: path with action to be enetered in service mode menu.
        Example: '[1] BAND SELECTION/[1] BAND SELECTION SIM 1- VZW/[7] --Clear all bands/(...)'
        :return: bool with action status
        """
        return self.__ue.set_service_mode(mmi_code, actions_path)
